from rdkit import Chem
import numpy as np
m=Chem.MolFromMolFile('initial.mol',removeHs=False)
p=np.array([list(map(float,l.split()[1:])) for l in open('optimized.xyz').readlines()[2:]])
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
 print(i,j,round(np.linalg.norm(p[i]-p[j]),3))
for i in range(12):
 for j in range(i):
  if not m.GetBondBetweenAtoms(i,j) and np.linalg.norm(p[i]-p[j])<1.9:print('UNEXPECTED CONTACT',i,j,np.linalg.norm(p[i]-p[j]))
q=np.array(m.GetConformer().GetPositions())
for a in m.GetAtoms():
 if a.GetDegree()==4:
  ns=[n.GetIdx() for n in a.GetNeighbors()]
  v1=np.linalg.det(q[ns[:3]]-q[ns[3]])
  v2=np.linalg.det(p[ns[:3]]-p[ns[3]])
  print('Stereo',a.GetIdx(),v1*v2>0)
